<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,post,type Row}from'../technicians/api';
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),statusFilter=ref(''),typeFilter=ref(''),orders=ref<Row[]>([]),summary=ref<Row>({}),open=ref(false),workOrder=ref<Row>({}),tasks=ref<Row[]>([]),logs=ref<Row[]>([]),technicians=ref<Row[]>([]),assigned=ref('0'),nextStatus=ref('OPEN'),statusNote=ref('');const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return orders.value.filter(r=>(!statusFilter.value||r.status===statusFilter.value)&&(!typeFilter.value||r.work_order_type===typeFilter.value)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));});const transitions:Record<string,string[]>={OPEN:['ASSIGNED','IN_PROGRESS','CANCELLED','FAILED'],ASSIGNED:['OPEN','IN_PROGRESS','CANCELLED','FAILED'],IN_PROGRESS:['ON_SITE','COMPLETED','CANCELLED','FAILED'],ON_SITE:['IN_PROGRESS','COMPLETED','CANCELLED','FAILED'],FAILED:['OPEN','ASSIGNED','CANCELLED'],COMPLETED:[],CANCELLED:[]};const allowed=computed(()=>[String(workOrder.value.status||'OPEN'),...(transitions[String(workOrder.value.status||'OPEN')]||[]).filter(s=>!['IN_PROGRESS','ON_SITE','COMPLETED'].includes(s)||Number(workOrder.value.assigned_user_id)>0)]);const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const label=(v:any)=>String(v||'—').replaceAll('_',' ');const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>String(v).toUpperCase()==='COMPLETED'?'success':['FAILED','CANCELLED'].includes(String(v).toUpperCase())?'danger':['OPEN','ASSIGNED','IN_PROGRESS','ON_SITE','HIGH','URGENT'].includes(String(v).toUpperCase())?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';try{const d=await get<any>('/api/v1/work-orders?limit=200&offset=0');orders.value=d?.items||[];summary.value=d?.summary||{};if(show)notice.value='Work orders refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load work orders.';}finally{loading.value=false;}}async function show(r:Row){busy.value=true;try{const d=await get<any>(`/api/v1/work-orders/show/${r.id}`);workOrder.value=d?.work_order||{};tasks.value=d?.tasks||[];logs.value=d?.status_logs||[];technicians.value=d?.assignable_technicians||[];assigned.value=String(workOrder.value.assigned_user_id||0);nextStatus.value=String(workOrder.value.status||'OPEN');statusNote.value='';open.value=true;}catch(e){error.value=e instanceof Error?e.message:'Unable to load work order details.';}finally{busy.value=false;}}
async function command(url:string,payload:Row,message:string,question=''){if(question&&!confirm(question))return;busy.value=true;error.value='';try{await post(url,payload);notice.value=message;await load();if(workOrder.value.id)await show(workOrder.value);}catch(e){error.value=e instanceof Error?e.message:'Work-order action failed.';}finally{busy.value=false;}}async function assign(){await command('/api/v1/work-orders/assign',{work_order_id:workOrder.value.id,assigned_user_id:assigned.value},'Work order assignment updated.','Assign this work order to the selected technician?');}async function updateStatus(status=nextStatus.value){let note=statusNote.value.trim();if(['COMPLETED','FAILED','CANCELLED'].includes(status)&&!note){note=prompt(`Required note for ${label(status)}:`)||'';if(!note.trim())return;}if(!note)note=`Updated to ${label(status)}.`;await command('/api/v1/work-orders/status',{work_order_id:workOrder.value.id,status,note},`Work order updated to ${label(status)}.`);}async function taskAction(task:Row,complete:boolean){await command(complete?'/api/v1/work-orders/tasks/complete':'/api/v1/work-orders/tasks/reopen',{task_id:task.id},complete?'Task completed.':'Task reopened.',`${complete?'Mark':'Reopen'} this task?`);}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Field operations" title="Work Orders" description="Manage installations, repairs, technical visits, assignments, and field tasks."><template #actions><NxButton variant="secondary" :disabled="loading||busy" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><NxCard v-for="c in [['Open',summary.open_count,'Unassigned jobs'],['Assigned',summary.assigned_count,'Assigned to staff'],['Active',summary.active_count,'In progress / on site'],['Completed',summary.completed_count,'Finished jobs'],['Issues',summary.issue_count,'Failed / cancelled']]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-2xl font-bold">{{c[1]||0}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{c[2]}}</p></NxCard></section><NxToolbar><div class="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between"><div><h2 class="font-bold">Work Order Queue</h2><p class="text-sm text-[var(--nx-text-muted)]">{{filtered.length}} matching work orders</p></div><div class="flex flex-col gap-2 sm:flex-row"><select v-model="statusFilter" :class="inputClass+' sm:w-48'"><option value="">All Statuses</option><option v-for="s in ['OPEN','ASSIGNED','IN_PROGRESS','ON_SITE','COMPLETED','CANCELLED','FAILED']" :key="s">{{label(s)}}</option></select><select v-model="typeFilter" :class="inputClass+' sm:w-60'"><option value="">All Types</option><option v-for="t in ['ONT_INSTALLATION','TECHNICAL_VISIT','NO_INTERNET','LOS','RELOCATION','REPAIR','RECONNECTION','DISCONNECTION','NAP_CHECK','DROP_CABLE_REPLACEMENT','OTHER']" :key="t">{{label(t)}}</option></select><input v-model="search" type="search" placeholder="Search work order or subscriber…" :class="inputClass+' sm:w-80'"></div></div></NxToolbar>
<NxTableShell min-width="1120px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Work Order</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Title / Type</th><th class="px-4 py-3">Priority</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Assigned</th><th class="px-4 py-3">Schedule</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="8" class="p-12 text-center text-[var(--nx-text-muted)]">No work orders found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3"><b class="font-mono">{{r.work_order_no||`#${r.id}`}}</b><small class="block text-[var(--nx-text-muted)]">{{fmt(r.created_at)}}</small></td><td class="px-4 py-3"><b>{{r.subscriber_name||'—'}}</b><small class="block text-[var(--nx-text-muted)]">{{r.account_number||'—'}}</small></td><td class="max-w-sm px-4 py-3"><b>{{r.title||'—'}}</b><small class="block text-[var(--nx-text-muted)]">{{label(r.work_order_type)}}</small></td><td class="px-4 py-3"><NxBadge :tone="tone(r.priority)">{{r.priority}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{label(r.status)}}</NxBadge></td><td class="px-4 py-3">{{r.assigned_user_name||r.assigned_username||'Waiting for personnel'}}</td><td class="px-4 py-3">{{r.scheduled_date||'—'}} {{r.scheduled_time||''}}</td><td class="px-4 py-3 text-right"><NxButton variant="secondary" :disabled="busy" @click="show(r)">Manage</NxButton></td></tr></tbody></NxTableShell>
<NxModal :open="open" :title="workOrder.work_order_no||'Work Order Details'" :description="`Created ${fmt(workOrder.created_at)} · ${label(workOrder.status)}`" max-width="78rem" @close="open=false"><div class="grid gap-4 p-5 xl:grid-cols-[minmax(0,2fr)_minmax(320px,1fr)]"><div class="space-y-4"><NxCard title="Work Order Information"><div class="grid gap-4 md:grid-cols-3"><div class="md:col-span-3"><p class="text-xs uppercase text-[var(--nx-text-muted)]">Title</p><p class="font-bold">{{workOrder.title||'—'}}</p></div><div><p class="text-xs uppercase text-[var(--nx-text-muted)]">Type</p><p>{{label(workOrder.work_order_type)}}</p></div><div><p class="text-xs uppercase text-[var(--nx-text-muted)]">Priority</p><NxBadge :tone="tone(workOrder.priority)">{{workOrder.priority}}</NxBadge></div><div><p class="text-xs uppercase text-[var(--nx-text-muted)]">Assigned</p><p>{{workOrder.assigned_user_name||'Unassigned'}}</p></div><div class="md:col-span-3"><p class="text-xs uppercase text-[var(--nx-text-muted)]">Description</p><p class="whitespace-pre-wrap">{{workOrder.description||workOrder.notes||'—'}}</p></div></div></NxCard><NxCard title="Tasks" :description="`${tasks.length} field tasks`"><div class="space-y-3"><div v-for="t in tasks" :key="t.id" class="flex items-start justify-between gap-3 rounded-md bg-[var(--nx-surface-muted)] p-3"><div><b>{{t.task_name}}</b><small class="block text-[var(--nx-text-muted)]">{{Number(t.is_required)?'Required':'Optional'}}{{t.completed_at?` · Completed ${fmt(t.completed_at)}`:''}}</small><p v-if="t.notes" class="mt-1 text-sm">{{t.notes}}</p></div><div class="text-right"><NxBadge :tone="Number(t.is_completed)?'success':'warning'">{{Number(t.is_completed)?'DONE':'PENDING'}}</NxBadge><div class="mt-2"><NxButton v-if="!Number(t.is_completed)" variant="secondary" :disabled="busy||['COMPLETED','CANCELLED'].includes(workOrder.status)" @click="taskAction(t,true)">Mark Done</NxButton><NxButton v-else variant="secondary" :disabled="busy||['COMPLETED','CANCELLED'].includes(workOrder.status)" @click="taskAction(t,false)">Reopen</NxButton></div></div></div><p v-if="!tasks.length" class="py-8 text-center">No tasks.</p></div></NxCard><NxCard title="Status History" :description="`${logs.length} lifecycle entries`"><div class="max-h-80 space-y-3 overflow-auto"><div v-for="l in logs" :key="l.id" class="rounded-md bg-[var(--nx-surface-muted)] p-3"><div class="flex justify-between gap-2"><b>{{label(l.old_status)}} → {{label(l.new_status)}}</b><small>{{fmt(l.created_at)}}</small></div><p class="mt-1 text-sm text-[var(--nx-text-muted)]">{{l.full_name||l.username||'System'}} · {{l.note||'No note'}}</p></div><p v-if="!logs.length" class="py-8 text-center">No status history.</p></div></NxCard></div>
<div class="space-y-4"><NxCard title="Subscriber"><dl class="space-y-3 text-sm"><div><dt class="text-[var(--nx-text-muted)]">Name / Account</dt><dd class="font-semibold">{{workOrder.subscriber_name||'—'}} · {{workOrder.account_number||'—'}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Contact</dt><dd>{{workOrder.contact_number||workOrder.subscriber_contact_number||'—'}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Service</dt><dd>{{workOrder.service_number||workOrder.ppp_username||'—'}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Source Ticket</dt><dd>{{workOrder.ticket_no||'Not linked'}} {{workOrder.ticket_subject||''}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Location</dt><dd>{{workOrder.location||workOrder.subscriber_address||'—'}}</dd></div></dl></NxCard><NxCard title="Assignment"><label class="grid gap-2 text-sm font-semibold">Technician<select v-model="assigned" :class="inputClass"><option value="0">Unassigned</option><option v-for="t in technicians" :key="t.id" :value="t.id" :disabled="!['AVAILABLE',undefined].includes(t.attendance_status)&&String(t.id)!==String(workOrder.assigned_user_id)">{{t.full_name||t.username}} · {{label(t.attendance_status)}} · {{t.active_work_order_count||0}} active</option></select></label><NxButton class="mt-3 w-full" variant="secondary" :disabled="busy" @click="assign">Assign Work Order</NxButton></NxCard><NxCard title="Lifecycle"><label class="grid gap-2 text-sm font-semibold">Status<select v-model="nextStatus" :class="inputClass"><option v-for="s in ['OPEN','ASSIGNED','IN_PROGRESS','ON_SITE','COMPLETED','CANCELLED','FAILED']" :key="s" :disabled="!allowed.includes(s)">{{label(s)}}</option></select></label><label class="mt-3 grid gap-2 text-sm font-semibold">Status Note<textarea v-model="statusNote" rows="3" placeholder="Required for completion, failure, or cancellation" :class="inputClass"></textarea></label><NxButton class="mt-3 w-full" :disabled="busy||!allowed.includes(nextStatus)" @click="updateStatus()">Update Status</NxButton><div class="mt-3 grid grid-cols-2 gap-2"><NxButton v-if="allowed.includes('IN_PROGRESS')" variant="secondary" @click="updateStatus('IN_PROGRESS')">Start Job</NxButton><NxButton v-if="allowed.includes('ON_SITE')" variant="secondary" @click="updateStatus('ON_SITE')">On Site</NxButton><NxButton v-if="allowed.includes('COMPLETED')" @click="updateStatus('COMPLETED')">Complete</NxButton><NxButton v-if="allowed.includes('FAILED')" variant="danger" @click="updateStatus('FAILED')">Failed</NxButton></div></NxCard></div></div><template #footer><NxButton variant="secondary" @click="open=false">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="work-orders"]){max-width:100%;overflow-x:hidden}</style>
